<?php
if(!defined('ABSPATH'))exit;
function dgs_ps_types(){return array('stars'=>array('dgs_star','دانش‌آموزان برگزیده'),'gallery'=>array('dgs_gallery','گالری مدرسه'));}
function dgs_ps_post($kind,$id){$types=dgs_ps_types();$p=get_post($id);return isset($types[$kind])&&$p&&$p->post_type===$types[$kind][0]&&in_array($p->post_status,array('draft','publish','pending'),true)?$p:false;}
function dgs_ps_revision($p){return hash('sha256',wp_json_encode(array(dgs_news_revision($p),$p->post_excerpt,$p->menu_order,get_post_meta($p->ID,'_dgs_star_average',true),get_post_meta($p->ID,'_dgs_star_highlights',true),get_post_meta($p->ID,'_dgs_period',true),get_post_meta($p->ID,'_dgs_star_class',true),get_post_meta($p->ID,'_dgs_achievement',true))));}
function dgs_ps_save($kind,$d,$image=0){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','دسترسی مدیریت لازم است.');$types=dgs_ps_types();if(!isset($types[$kind]))return dgs_edu_error('kind','بخش معتبر نیست.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','اطلاعات فرم معتبر نیست.');
 $id=absint($d['item_id']??0);$p=$id?dgs_ps_post($kind,$id):false;if($id&&!$p)return dgs_edu_error('scope','این مورد متعلق به این بخش نیست.');$title=sanitize_text_field($d['item_title']??'');$body=sanitize_textarea_field($d['item_body']??'');$status=$d['item_status']??'draft';$period=$d['period']??'week';if(!$title||dgs_edu_length($title)>200||dgs_edu_length($body)>5000)return dgs_edu_error('fields','عنوان تا۲۰۰ نویسه و توضیح تا۵۰۰۰ نویسه باشد.');if(!in_array($status,array('draft','publish'),true))return dgs_edu_error('status','وضعیت معتبر نیست.');if($kind==='stars'&&!in_array($period,array('week','month','term','year'),true))return dgs_edu_error('period','بازه برگزیده معتبر نیست.');
 if($image&&!dgs_showcase_image_valid($image))return dgs_edu_error('image','تصویر معتبر نیست.');$thumb=$image?:((($d['remove_image']??'')==='1')?0:($id?get_post_thumbnail_id($id):0));if($kind==='gallery'&&$status==='publish'&&!dgs_showcase_image_valid($thumb))return dgs_edu_error('image','برای انتشار در گالری عکس انتخاب کنید.');
 if($kind==='stars'){ $avg=dgs_edu_digits((string)($d['average']??''));if($avg!==''&&(!is_numeric($avg)||(float)$avg<0||(float)$avg>20))return dgs_edu_error('average','میانگین باید عددی از صفر تا۲۰ باشد.');if(dgs_edu_length((string)($d['highlights']??''))>2000)return dgs_edu_error('highlights','موفقیت‌ها حداکثر۲۰۰۰ نویسه باشد.');}
 $lock='dgs_ps_'.($id?:get_current_user_id().'_'.$kind);if(!add_option($lock,time(),'','no'))return dgs_edu_error('busy','ذخیره در جریان است؛ دوباره تلاش کنید.');try{
 if($id&&(!($p=dgs_ps_post($kind,$id))||!hash_equals(dgs_ps_revision($p),(string)($d['item_revision']??''))))return dgs_edu_error('stale','اطلاعات تغییر کرده؛ صفحه ویرایش را دوباره باز کنید.');
 $meta=array('_thumbnail_id'=>$thumb);if($kind==='stars')$meta+=array('_dgs_star_average'=>$avg,'_dgs_star_highlights'=>sanitize_textarea_field($d['highlights']??''),'_dgs_period'=>$period,'_dgs_star_class'=>sanitize_text_field($d['star_class']??''),'_dgs_achievement'=>sanitize_text_field($d['achievement']??''));
 $row=array('post_type'=>$types[$kind][0],'post_title'=>$title,'post_status'=>$status,'meta_input'=>$meta,'menu_order'=>max(0,min(9999,(int)($d['item_order']??0))));$row[$kind==='gallery'?'post_excerpt':'post_content']=$body;if($id)$row['ID']=$id;else $row['post_author']=get_current_user_id();$saved=wp_insert_post(wp_slash($row),true);if(is_wp_error($saved)||!$saved)return dgs_edu_error('save','ذخیره انجام نشد.');if($kind==='gallery')dgs_gallery_invalidate($saved);else dgs_catalog_invalidate($saved);dgs_edu_audit('school_'.$kind.'_save',$saved);return $saved;
 }finally{delete_option($lock);}
}
add_action('admin_post_dgs_panel_showcase',function(){
 if(!current_user_can('dgs_manage_education')||($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('دسترسی ندارید.','',array('response'=>403));check_admin_referer('dgs_panel_showcase','showcase_nonce');$d=wp_unslash($_POST);$kind=is_string($d['kind']??null)?$d['kind']:'';if(!isset(dgs_ps_types()[$kind]))wp_die('بخش معتبر نیست.');$id=is_scalar($d['item_id']??null)?absint($d['item_id']):0;if($id&&!dgs_ps_post($kind,$id))wp_die('مورد مجاز نیست.','',array('response'=>403));$image=dgs_news_photo();$r=is_wp_error($image)?$image:dgs_ps_save($kind,$d,$image);if(is_wp_error($r)&&is_int($image)&&$image)wp_delete_attachment($image,true);$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('error'=>is_wp_error($r),'text'=>is_wp_error($r)?$r->get_error_message():'اطلاعات ذخیره شد.'),300);$args=array('dg_notice'=>$token);if(is_wp_error($r)){set_transient('dgs_ps_form_'.get_current_user_id().'_'.$token,$d,300);$args['item_edit']=$id?:'new';}wp_safe_redirect(add_query_arg($args,dgs_edu_url($kind,dgs_edu_current_year())),303);exit;
});
function dgs_edu_view_stars($year){return dgs_ps_view('stars',$year);}
function dgs_edu_view_gallery($year){return dgs_ps_view('gallery',$year);}
function dgs_ps_view($kind,$year){
 if(!current_user_can('dgs_manage_education'))return '';$types=dgs_ps_types();$base=dgs_edu_url($kind,$year);$edit=dgs_att_get('item_edit');$periods=array('week'=>'هفته','month'=>'ماه','term'=>'ترم','year'=>'سال');$h='<div class="dsp-school">'.dgs_school_title($types[$kind][1],$kind==='stars'?'آخرین برگزیده منتشرشده هر بازه در صفحه اصلی نمایش داده می‌شود.':'تصاویر منتشرشده در صفحه اصلی و گالری کامل نمایش داده می‌شوند.');
 if($edit!==''){$id=$edit==='new'?0:absint($edit);$p=$id?dgs_ps_post($kind,$id):false;if($edit!=='new'&&!$p)return $h.dgs_empty('مورد پیدا نشد.').'</div>';$d=array('item_title'=>$p?$p->post_title:'','item_body'=>$p?($kind==='gallery'?$p->post_excerpt:$p->post_content):'','item_status'=>$p&&$p->post_status==='publish'?'publish':'draft','item_order'=>$p?$p->menu_order:0,'item_revision'=>$p?dgs_ps_revision($p):'','average'=>$p?get_post_meta($id,'_dgs_star_average',true):'','highlights'=>$p?get_post_meta($id,'_dgs_star_highlights',true):'','period'=>$p?get_post_meta($id,'_dgs_period',true):'week','star_class'=>$p?get_post_meta($id,'_dgs_star_class',true):'','achievement'=>$p?get_post_meta($id,'_dgs_achievement',true):'');$token=dgs_att_get('dg_notice');$key='dgs_ps_form_'.get_current_user_id().'_'.$token;$old=$token?get_transient($key):false;if(is_array($old)){foreach(array_keys($d) as $k)if(is_scalar($old[$k]??null))$d[$k]=$old[$k];delete_transient($key);}
 $h.='<section class="dsp-card"><a class="dg-btn dg-btn-outline" href="'.esc_url($base).'">بازگشت به فهرست</a><form class="dge-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_panel_showcase','showcase_nonce',true,false).'<input type="hidden" name="action" value="dgs_panel_showcase"><input type="hidden" name="kind" value="'.esc_attr($kind).'"><input type="hidden" name="item_id" value="'.$id.'"><input type="hidden" name="item_revision" value="'.esc_attr($d['item_revision']).'"><label>'.($kind==='stars'?'نام و نام خانوادگی دانش‌آموز':'عنوان تصویر').'<input name="item_title" maxlength="200" required value="'.esc_attr($d['item_title']).'"></label>';
 if($kind==='stars'){$h.=dgs_edu_select('period','برگزیدهٔ',$periods,$d['period']);foreach(array('star_class'=>'پایه و رشته','achievement'=>'عنوان موفقیت') as $k=>$label)$h.='<label>'.$label.'<input name="'.$k.'" value="'.esc_attr($d[$k]).'" maxlength="500"></label>';}
 if($kind==='stars')$h.='<label>میانگین (اختیاری، از صفر تا۲۰)<input name="average" inputmode="decimal" value="'.esc_attr($d['average']).'"></label><label>موفقیت‌ها (اختیاری؛ هر خط یک مورد)<textarea name="highlights" maxlength="2000" rows="4">'.esc_textarea($d['highlights']).'</textarea></label>';
 if($kind==='gallery') $h.='<label>ترتیب نمایش (عدد کمتر زودتر)<input type="number" name="item_order" min="0" max="9999" value="'.esc_attr($d['item_order']).'"></label>';
 $h.='<label>توضیحات (اختیاری)<textarea name="item_body" rows="5" maxlength="5000">'.esc_textarea($d['item_body']).'</textarea></label><label>عکس JPG/PNG/WebP تا۳مگابایت<input type="file" name="news_photo" accept="image/jpeg,image/png,image/webp"></label>';if($id&&has_post_thumbnail($id))$h.=get_the_post_thumbnail($id,'thumbnail').'<label><input type="checkbox" name="remove_image" value="1">برداشتن عکس فعلی</label>';
 return $h.dgs_edu_select('item_status','وضعیت',array('draft'=>'پیش‌نویس / عدم نمایش در سایت','publish'=>'انتشار در سایت'),$d['item_status']).'<button class="dg-btn">ذخیره</button></form></section></div>';}
 $page=max(1,absint(dgs_att_get('item_page','1')));$q=new WP_Query(array('post_type'=>$types[$kind][0],'post_status'=>array('draft','publish','pending'),'posts_per_page'=>15,'paged'=>$page,'orderby'=>$kind==='gallery'?array('menu_order'=>'ASC','date'=>'DESC','ID'=>'DESC'):array('date'=>'DESC','ID'=>'DESC')));$h.='<section class="dsp-card"><a class="dg-btn" href="'.esc_url(add_query_arg('item_edit','new',$base)).'">افزودن '.($kind==='stars'?'برگزیده':'تصویر').'</a>'.dgs_edu_table_start(array('عکس','عنوان',$kind==='stars'?'بازه':'ترتیب','وضعیت','عملیات'));foreach($q->posts as $p)$h.='<tr><td>'.get_the_post_thumbnail($p->ID,array(64,64)).'</td><td>'.esc_html($p->post_title).'</td><td>'.esc_html($kind==='stars'?($periods[get_post_meta($p->ID,'_dgs_period',true)]??'—'):$p->menu_order).'</td><td>'.($p->post_status==='publish'?'منتشرشده':'پیش‌نویس / در انتظار').'</td><td><a class="dge-small-btn" href="'.esc_url(add_query_arg('item_edit',$p->ID,$base)).'">ویرایش / تغییر انتشار</a></td></tr>';if(!$q->posts)$h.='<tr><td colspan="5">هنوز موردی ثبت نشده است.</td></tr>';$h.='</tbody></table></div>';if($page>1)$h.='<a class="dg-btn" href="'.esc_url(add_query_arg('item_page',$page-1,$base)).'">قبلی</a>';if($page<$q->max_num_pages)$h.='<a class="dg-btn" href="'.esc_url(add_query_arg('item_page',$page+1,$base)).'">بعدی</a>';return $h.'</section></div>';
}
